// Package pricing holds list prices for the clouds a cluster may run on today (AWS, Azure) and for the EU providers
// it could move to (UpCloud, Hetzner, Scaleway, OVHcloud).
// The JSON files in data/ are generated by tools/pricegen from the providers' own price APIs and embedded at build time,
// so the analyzer never needs cloud credentials or internet access inside the cluster.
package pricing

import (
	"embed"
	"encoding/json"
	"fmt"
	"slices"
	"sort"
	"strings"
)

// HoursPerMonth is the usual cloud billing month (365 * 24 / 12).
const HoursPerMonth = 730.0

// Cloud is the price list of one current provider (AWS, Azure), in its billing currency.
type Cloud struct {
	Provider  string             `json:"provider"`
	Currency  string             `json:"currency"`
	Generated string             `json:"generated"`
	Source    string             `json:"source"`
	Regions   map[string]*Region `json:"regions"`
}

// Region prices. Missing values are 0 and are reported as "not priced" rather than guessed.
type Region struct {
	Instances          map[string]float64 `json:"instances"`                    // instance type -> on-demand price per hour (Linux)
	StorageGBMonth     map[string]float64 `json:"storageGBMonth,omitempty"`     // volume type (gp3, gp2, ...) -> price per GB-month
	ControlPlaneHourly float64            `json:"controlPlaneHourly,omitempty"` // managed Kubernetes fee per cluster-hour
	LoadBalancerHourly float64            `json:"loadBalancerHourly,omitempty"` // one network load balancer, hourly part only
}

// UpCloud is the UpCloud price list in EUR.
type UpCloud struct {
	Currency  string                  `json:"currency"`
	Generated string                  `json:"generated"`
	Source    string                  `json:"source"`
	Zones     map[string]*UpCloudZone `json:"zones"`
}

type UpCloudZone struct {
	Plans                []Plan             `json:"plans"`
	StorageMaxIOPSMonth  float64            `json:"storageMaxiopsGBMonth"` // per GB-month
	StorageStandardMonth float64            `json:"storageStandardGBMonth,omitempty"`
	LoadBalancerMonthly  float64            `json:"loadBalancerMonthly,omitempty"` // managed load balancer plan used in estimates
	ControlPlaneMonthly  float64            `json:"controlPlaneMonthly,omitempty"` // managed Kubernetes (UKS) control plane used in estimates
	LoadBalancerPlans    map[string]float64 `json:"loadBalancerPlans,omitempty"`   // all managed load balancer plans, per month
	KubernetesPlans      map[string]float64 `json:"kubernetesPlans,omitempty"`     // all UKS control plane plans, per month
}

// Plan is one server plan of a target provider.
type Plan struct {
	Name      string  `json:"name"`
	Fam       string  `json:"family,omitempty"` // general, compute, memory, shared, ...; empty for UpCloud, where the name tells
	Cores     int     `json:"cores"`
	MemoryMiB int     `json:"memoryMiB"`
	StorageGB int     `json:"storageGB,omitempty"`
	Monthly   float64 `json:"monthly"`
}

// Provider is the price list of one EU provider in one region, in EUR. The files are generated by
// `pricegen eu` from the open EU Cloud Price Index (github.com/moveinfra/eu-cloud-prices).
type Provider struct {
	ID        string `json:"provider"`
	Name      string `json:"name"`
	Region    string `json:"region"`
	Location  string `json:"location,omitempty"`
	Currency  string `json:"currency"`
	Generated string `json:"generated"`
	Source    string `json:"source"`
	Note      string `json:"note,omitempty"`
	Plans     []Plan `json:"plans"`

	StorageGBMonth      float64 `json:"storageGBMonth"`
	StorageProduct      string  `json:"storageProduct,omitempty"`
	LoadBalancerMonthly float64 `json:"loadBalancerMonthly"`
	LoadBalancerProduct string  `json:"loadBalancerProduct,omitempty"`
	// ControlPlaneMonthly is the managed Kubernetes control plane. 0 with an empty ControlPlaneProduct means the
	// provider has no managed Kubernetes and the control plane is self-managed.
	ControlPlaneMonthly float64 `json:"controlPlaneMonthly"`
	ControlPlaneProduct string  `json:"controlPlaneProduct,omitempty"`
}

// ProviderIDs are the EU providers with a data file, besides UpCloud.
var ProviderIDs = []string{"hetzner", "ovhcloud", "scaleway"}

// Target is one provider in one zone, resolved for the estimator: the same shape for every provider.
type Target struct {
	ID, Name, Zone, Generated, Note string
	Plans                           []Plan // plans allowed for worker nodes, cheapest first
	All                             []Plan // every plan, cheapest first
	StorageGBMonth                  float64
	StorageProduct                  string
	StorageStandardGBMonth          float64 // UpCloud Standard tier, used for clusters already on UpCloud
	LoadBalancerMonthly             float64
	LoadBalancerProduct             string
	ControlPlaneMonthly             float64
	ControlPlaneProduct             string
	SelfManaged                     bool // no managed Kubernetes: the control plane runs on your own servers
}

// FX holds exchange rates as units of currency per 1 EUR (ECB reference rates).
type FX struct {
	Date  string             `json:"date"`
	Rates map[string]float64 `json:"rates"`
}

//go:embed data/*.json
var files embed.FS

// Book is everything the estimator needs, loaded from the embedded files.
type Book struct {
	Clouds    map[string]*Cloud // provider id (aws, azure) -> prices
	UpCloud   *UpCloud
	Providers map[string]*Provider // provider id (hetzner, ovhcloud, scaleway) -> prices
	FX        *FX
}

// Load reads the embedded price data.
func Load() (*Book, error) {
	b := &Book{Clouds: map[string]*Cloud{}, Providers: map[string]*Provider{}}
	for _, p := range []string{"aws", "azure"} {
		c := &Cloud{}
		if err := read("data/"+p+".json", c); err != nil {
			return nil, err
		}
		b.Clouds[p] = c
	}
	b.UpCloud = &UpCloud{}
	if err := read("data/upcloud.json", b.UpCloud); err != nil {
		return nil, err
	}
	for _, id := range ProviderIDs {
		p := &Provider{}
		if err := read("data/"+id+".json", p); err != nil {
			return nil, err
		}
		b.Providers[id] = p
	}
	b.FX = &FX{}
	if err := read("data/fx.json", b.FX); err != nil {
		return nil, err
	}
	return b, nil
}

func read(name string, v any) error {
	raw, err := files.ReadFile(name)
	if err != nil {
		return err
	}
	if err := json.Unmarshal(raw, v); err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	return nil
}

// ToEUR converts an amount in currency cur to EUR. ok is false for an unknown currency.
func (f *FX) ToEUR(amount float64, cur string) (float64, bool) {
	if strings.EqualFold(cur, "EUR") {
		return amount, true
	}
	r := f.Rates[strings.ToUpper(cur)]
	if r == 0 {
		return 0, false
	}
	return amount / r, true
}

// Family is the plan family. UpCloud plans carry it in the name: the upper-case prefix (DEV, STARTER, PREMIUM, HICPU,
// HIMEM, CLOUDNATIVE) or "general" for General Purpose plans, which have none (2xCPU-4GB).
func (p Plan) Family() string {
	if p.Fam != "" {
		return p.Fam
	}
	if prefix, _, ok := strings.Cut(p.Name, "-"); ok && prefix != "" && prefix == strings.ToUpper(prefix) && !strings.ContainsAny(prefix[:1], "0123456789") {
		return prefix
	}
	return "general"
}

// Zone returns the UpCloud zone's prices, keeping only plans of the given families (all when none are given),
// sorted cheapest first.
func (u *UpCloud) Zone(name string, families ...string) (*UpCloudZone, error) {
	src := u.Zones[name]
	var z *UpCloudZone
	if src != nil {
		cp := *src
		cp.Plans = nil
		for _, p := range src.Plans {
			if len(families) == 0 || slices.ContainsFunc(families, func(f string) bool { return strings.EqualFold(f, p.Family()) }) {
				cp.Plans = append(cp.Plans, p)
			}
		}
		z = &cp
	}
	if z == nil || len(z.Plans) == 0 {
		names := make([]string, 0, len(u.Zones))
		for n := range u.Zones {
			names = append(names, n)
		}
		sort.Strings(names)
		return nil, fmt.Errorf("no UpCloud prices for zone %q (known: %s)", name, strings.Join(names, ", "))
	}
	sort.SliceStable(z.Plans, func(i, j int) bool { return z.Plans[i].Monthly < z.Plans[j].Monthly })
	return z, nil
}

// TargetIDs lists the providers the book can price a move to, in a fixed order.
func (b *Book) TargetIDs() []string {
	ids := []string{}
	if b.UpCloud != nil {
		ids = append(ids, "upcloud")
	}
	for id := range b.Providers {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// Target resolves one provider for the estimator. zone and families apply to UpCloud only (the other providers have
// one price region each); empty families means the provider's production plans.
func (b *Book) Target(id, zone string, families ...string) (*Target, error) {
	if id == "upcloud" && b.UpCloud != nil {
		z, err := b.UpCloud.Zone(zone, families...)
		if err != nil {
			return nil, err
		}
		all, _ := b.UpCloud.Zone(zone)
		return &Target{ID: id, Name: "UpCloud", Zone: zone, Generated: b.UpCloud.Generated, Plans: z.Plans, All: all.Plans,
			StorageGBMonth: z.StorageMaxIOPSMonth, StorageProduct: "MaxIOPS", StorageStandardGBMonth: z.StorageStandardMonth,
			LoadBalancerMonthly: z.LoadBalancerMonthly, LoadBalancerProduct: "Managed Load Balancer",
			ControlPlaneMonthly: z.ControlPlaneMonthly, ControlPlaneProduct: "Managed Kubernetes"}, nil
	}
	p := b.Providers[id]
	if p == nil {
		return nil, fmt.Errorf("no prices for provider %q (known: %s)", id, strings.Join(b.TargetIDs(), ", "))
	}
	if len(families) == 0 {
		families = []string{"general", "compute", "memory"} // dedicated-CPU plans; shared-CPU plans are left out
	}
	t := &Target{ID: id, Name: p.Name, Zone: p.Region, Generated: p.Generated, Note: p.Note,
		StorageGBMonth: p.StorageGBMonth, StorageProduct: p.StorageProduct,
		LoadBalancerMonthly: p.LoadBalancerMonthly, LoadBalancerProduct: p.LoadBalancerProduct,
		ControlPlaneMonthly: p.ControlPlaneMonthly, ControlPlaneProduct: p.ControlPlaneProduct,
		SelfManaged: p.ControlPlaneMonthly == 0 && p.ControlPlaneProduct == ""}
	t.All = slices.Clone(p.Plans)
	sort.SliceStable(t.All, func(i, j int) bool { return t.All[i].Monthly < t.All[j].Monthly })
	for _, pl := range t.All {
		if slices.ContainsFunc(families, func(f string) bool { return strings.EqualFold(f, pl.Family()) }) {
			t.Plans = append(t.Plans, pl)
		}
	}
	if len(t.Plans) == 0 {
		return nil, fmt.Errorf("no %s plans of families %s", p.Name, strings.Join(families, ", "))
	}
	return t, nil
}
